from taf.hw.optical_switch import optical_switch

from taf.rfrl.procedures.resources.python.logger import (
    log_result,
    log_input_and_output,
)
from taf.rfrl.procedures.resources.python.optical_switch.exceptions import (
    OpticalSwitchConfigurationError,
)


class OpticalSwitch:
    """
    Class for optical switch - used for optical links operations with RMODs
    """

    def __init__(self):
        self._api = optical_switch()

    @log_input_and_output
    def get_rmod_optical_links_config(self, rmod_optical_switch_channels):
        """
        Gets optical links config for particular RMOD.
        :param rmod_optical_switch_channels: configuration of optical switch channels for particular RMOD
                                             Optical switch channels configuration is defined in init file
                                             under following paths:
                                             -For GNB bts type:
                                                 "tl.gnbs[0].dus[0].rus[rmod_index].optical_switch_channels"
                                             -For ENB bts type:
                                                 "tl.enbs[0].rms[rmod_index].optical_switch_channels"
        :type rmod_optical_switch_channels: list
        :return: RMOD's optical links configuration, example:
                 [{'link_id': 1,
                   'optical_switch': <taf.config.testline.optical_switch.Leoni object at 0x7fd23a20d100>,
                   'module_no': 4,
                   'channel_no': 1,
                   'channel_amount': 4},
                  {'link_id': 2,
                   'optical_switch': <taf.config.testline.optical_switch.Leoni object at 0x7fd23a20d100>,
                   'module_no': 5,
                   'channel_no': 1,
                   'channel_amount': 4}]
        :rtype: list(dict)
        """
        optical_switch_channels = rmod_optical_switch_channels if rmod_optical_switch_channels is not None else []

        rmod_optical_links_config = []
        for channel_index, optical_switch_channel in enumerate(optical_switch_channels, 1):
            rmod_optical_link_config = {"link_id": channel_index,
                                        "optical_switch": optical_switch_channel.optical_switch,
                                        "module_no": optical_switch_channel.switch_module.module_no,
                                        "channel_no": optical_switch_channel.channel_no,
                                        "channel_amount": optical_switch_channel.switch_module.channel_amount,
                                        }
            rmod_optical_links_config.append(rmod_optical_link_config)

        if not rmod_optical_links_config:
            raise OpticalSwitchConfigurationError(f"Missing optical links configuration in "
                                                  f"{rmod_optical_switch_channels}")

        return rmod_optical_links_config

    @log_input_and_output
    def set_rmod_optical_link(self, rmod_optical_link_config, destination_channel_id):
        """
        Sets RMOD's optical link to particular channel id.
        :param rmod_optical_link_config: RMOD's optical link configuration, example:
                  {'link_id': 1,
                   'optical_switch': <taf.config.testline.optical_switch.Leoni object at 0x7fd23a20d100>,
                   'module_no': 4,
                   'channel_no': 1,
                   'channel_amount': 4}
        :type rmod_optical_link_config: dict
        :param destination_channel_id: id of RMOD's optical channel id to set
        :type destination_channel_id: str or int
        """
        optical_switch_config = rmod_optical_link_config["optical_switch"]

        self._api.setup_optical_switch(optical_switch=optical_switch_config.__class__.__name__,
                                       model=optical_switch_config.model,
                                       addr=optical_switch_config.addr,
                                       port=optical_switch_config.port)

        module_number = rmod_optical_link_config["module_no"]

        try:
            self._api.set_optical_switch_channels(settings={int(module_number): int(destination_channel_id)})
            log_result(f"Module number: '{module_number}' has been set to destination channel id: "
                       f"'{destination_channel_id}' on optical switch device: {optical_switch_config}")
        finally:
            self._api.teardown()
